package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaElDraft1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_bismillah_la_yadurru" to DuaText("Προστασία από κάθε βλάβη", "Στο όνομα του Αλλάχ, με το όνομα του οποίου τίποτα στη γη ή στους ουρανούς δεν μπορεί να προκαλέσει κακό, και Αυτός είναι ο Παντός, ο Παντογνώστης.", "Τρεις φορές κάθε πρωί και βράδυ.", "Όποιος το πει τρεις φορές πρωί και βράδυ, τίποτα δεν θα του κάνει κακό."),
        "dua_raditu_billahi" to DuaText("Ικανοποίηση με τον Αλλάχ ως Κύριο", "Είμαι ευχαριστημένος με τον Αλλάχ ως Κύριό μου, με το Ισλάμ ως θρησκεία μου και με τον Μωάμεθ ﷺ ως Προφήτη μου.", "Τρεις φορές πρωί και βράδυ.", "Αποτελεί δικαίωμα στον Αλλάχ να τον ευχαριστεί την Ημέρα της Κρίσεως."),
        "dua_hasbiyallah" to DuaText("Hasbiyallah (Ο Αλλάχ είναι αρκετός)", "Ο Αλλάχ είναι αρκετός για μένα. δεν υπάρχει θεός εκτός από Αυτόν. Σε Αυτόν εναποθέτω την εμπιστοσύνη μου και είναι ο Κύριος του Ισχυρού Θρόνου.", "Επτά φορές πρωί και βράδυ.", "Ένας στίχος του Κορανίου. Ο Αλλάχ αρκείται ενάντια στις ανησυχίες αυτού του κόσμου και του επέκεινα."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("SubhanAllahi wa bihamdihi", "Δόξα να είναι ο Αλλάχ και όλος ο έπαινος είναι δικός του.", "Εκατό φορές την ημέρα.", "Όποιος το λέει εκατό φορές τη μέρα, του συγχωρούνται οι αμαρτίες, κι ας είναι σαν τον αφρό της θάλασσας."),
        "dua_tahleel_100" to DuaText("La ilaha illallahu wahdahu", "Κανείς δεν είναι άξιος λατρείας εκτός από τον Αλλάχ, τον Μοναδικό, που δεν έχει κανέναν εταίρο. Δική του είναι η κυριαρχία και δικός του είναι ο έπαινος, και έχει δύναμη πάνω σε όλα τα πράγματα.", "Μεγάλη αρετή να το λες εκατό φορές την ημέρα.", "Η ανταμοιβή της απελευθέρωσης δέκα σκλάβων, εκατό καλών πράξεων γραμμένων, εκατό αμαρτιών διαγραμμένων και προστασίας από τον Σαϊτάν μέχρι το βράδυ."),
        "dua_leaving_mosque" to DuaText("Φεύγοντας από το Τζαμί", "Ω Αλλάχ, Σου ζητώ την γενναιοδωρία Σου.", "Όταν βγαίνεις από το τζαμί με το αριστερό πόδι.", "Ζητώντας τη γενναιοδωρία και την προμήθεια του Αλλάχ όταν φεύγετε από το τζαμί."),
        "dua_after_adhan" to DuaText("Μετά το Αντάν", "Ω Αλλάχ, Κύριε αυτής της τέλειας κλήσης και της προσευχής που πρόκειται να πραγματοποιηθεί, δώρισε στον Μωάμεθ ﷺ al-Wasilah και αρετή και ανέβασέ τον στον Επαινούμενο Σταθμό που του υποσχέθηκες.", "Αφού ολοκληρωθεί το αντάν.", "Όποιος το πει αυτό θα του δοθεί η μεσολάβηση του Προφήτη ﷺ την Ημέρα της Κρίσεως."),
        "dua_after_salah_istighfar" to DuaText("Μετά τον Φαρντ Σαλάχ", "Ζητώ τη συγχώρεση του Αλλάχ (3 φορές). Ω Αλλάχ, είσαι σα-σαλάμ και από Σένα είναι η ειρήνη. Ευλογημένος είσαι, ω Κάτοχος της Μεγαλειότητας και της Τιμής.", "Αμέσως μετά το σαλάμ.", "Ο Προφήτης ﷺ το απήγγειλε αυτό μετά από κάθε υποχρεωτική προσευχή."),
        "dua_after_salah_help_dhikr" to DuaText("Βοήθησέ με να σε θυμάμαι", "Ω Αλλάχ, βοήθησέ με να Σε θυμάμαι, να Σε ευχαριστώ και να Σε λατρεύω με τον καλύτερο τρόπο.", "Μετά από κάθε προσευχή — ο Προφήτης ﷺ συμβούλεψε τον Muadh (RA) να την πει.", "Μια ειδική συμβουλή του Προφήτη ﷺ — αριστεία και σταθερότητα στη λατρεία."),
        "dua_sleep_tasbeeh" to DuaText("Tasbeeh-e-Fatimi πριν από τον ύπνο", "Δόξα στον Αλλάχ (33), όλος ο έπαινος είναι για τον Αλλάχ (33), ο Αλλάχ είναι ο Μεγαλύτερος (34).", "Πριν κοιμηθεί — ο Προφήτης ﷺ το δίδαξε στη Φατιμά και στον Αλί (RA).", "Ο Προφήτης ﷺ είπε ότι είναι καλύτερο για σένα από έναν υπηρέτη."),
        "dua_sleep_qina_adhab" to DuaText("Προστασία από τιμωρία", "Ω Αλλάχ, προστάτεψε με από την τιμωρία Σου την ημέρα που θα αναστήσεις τους δούλους Σου.", "Τρεις φορές, με το δεξί χέρι κάτω από το μάγουλο.", "Μετατρέπει τον ύπνο σε υπενθύμιση θανάτου και προετοιμασίας για το Έπειτα."),
        "dua_bad_dream" to DuaText("Μετά από ένα κακό όνειρο", "Αναζητώ καταφύγιο στον Αλλάχ από τον Σαϊτάν, τον καταραμένο.", "Μετά από ένα κακό όνειρο: στεγνώστε ελαφρά προς τα αριστερά τρεις φορές και μετά στρίψτε στην άλλη πλευρά.", "Το κακό όνειρο δεν θα σας βλάψει. μην το πεις σε κανέναν."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("Ya Hayyu Ya Qayyum", "Ω Πάντα Ζωντανός, Ω Συντηρητής όλων! Με το έλεός Σου ζητώ βοήθεια.", "Όταν ένα θέμα γίνεται πολύ βαρύ.", "Όποτε κάτι στενοχωρούσε τον Προφήτη ﷺ, το έλεγε αυτό."),
        "dua_entering_market" to DuaText("Μπαίνοντας στο Marketplace", "Κανείς δεν είναι άξιος λατρείας εκτός από τον Αλλάχ, τον Μοναδικό, που δεν έχει κανέναν εταίρο. Δική του είναι η κυριαρχία και δικός του είναι ο έπαινος. Δίνει ζωή και προκαλεί θάνατο, και είναι Πάντα Ζων και δεν πεθαίνει ποτέ. Στο χέρι Του είναι όλα τα καλά, και έχει δύναμη πάνω σε όλα τα πράγματα.", "Κατά την είσοδο στην αγορά.", "Το χαντίθ αναφέρει μια μεγάλη ανταμοιβή για αυτό (ένα εκατομμύριο καλές πράξεις)."),
        "dua_adam_forgiveness" to DuaText("Δούα του Προφήτη Αδάμ (AS)", "Κύριε μας, αδικήσαμε τους εαυτούς μας, και αν δεν μας συγχωρήσεις και δεν μας ελεήσεις, σίγουρα θα είμαστε ανάμεσα στους ηττημένους.", "Το ντουά της μετάνοιας του Αδάμ και του Χάουα (AS).", "Η πρώτη μετάνοια της ανθρωπότητας - ο Αλλάχ τη δέχτηκε."),
        "dua_abu_bakr" to DuaText("Η Ντούα δίδαξε στον Αμπού Μπακρ το (RA)", "Ω Αλλάχ, αδίκησα πολύ τον εαυτό μου, και κανείς δεν συγχωρεί αμαρτίες εκτός από Εσένα, γι' αυτό δώσε μου συγχώρεση από τον εαυτό σου και ελέησέ με. Πράγματι, Εσύ είσαι ο Συγχωρητής, ο Ελεήμων.", "Ο Προφήτης ﷺ το δίδαξε στον Abu Bakr as-Siddiq (RA) να λέει στην προσευχή (μετά το tashahhud).", "Ένα Sunnah dua για το τέλος της προσευχής."),
        "dua_astaghfirullah_atubu" to DuaText("Καθημερινή Istighfar", "Ζητώ τη συγχώρεση του Αλλάχ και στρέφομαι σε Αυτόν με μετάνοια.", "Ο Προφήτης ﷺ ζητούσε συγχώρεση περισσότερες από εβδομήντα φορές την ημέρα.", "Ο Προφήτης ﷺ είπε: Ζητώ τη συγχώρεση του Αλλάχ και μετανοώ σε Αυτόν περισσότερες από εβδομήντα φορές την ημέρα."),
        "dua_laylatul_qadr" to DuaText("Dua για το Laylat al-Qadr", "Ω Αλλάχ, είσαι πολύ επιεικής και σου αρέσει να συγχωρείς, γι' αυτό συγχώρεσέ με.", "Δίδαξε στην Aisha (RA) για το Laylat al-Qadr.", "Μια ιδιαίτερη ντουέτα για τις τελευταίες νύχτες του Ραμαζανιού και του Laylat al-Qadr."),
        "dua_family_coolness" to DuaText("Coolness of the Eyes (Σύζυγος & Παιδιά)", "Κύριε μας, χάρισε μας από τους συζύγους και τους απογόνους μας την ψυχραιμία των ματιών μας και κάνε μας αρχηγούς των δικαίων.", "Μια κορανική ντουέτα για μια δίκαιη σύζυγο και παιδιά.", "Για ειρήνη στο σπίτι και δίκαια παιδιά."),
        "dua_righteous_children" to DuaText("Για Δίκαιους Απόγονους", "Κύριε μου, χάρισε μου από τον εαυτό σου αγνούς απογόνους. Πράγματι, Εσύ είσαι ο Ακούς της ικεσίας.", "Η ντουά του Προφήτη Ζακαρίγγια (AS).", "Μια κορανική ντουέτα για όσους αναζητούν παιδιά."),
        "dua_ibrahim_prayer_family" to DuaText("Ιδρυτές της Προσευχής", "Κύριε μου, κάνε με θεμελιωτή της προσευχής, και από τους απογόνους μου. Κύριε μας, δέξου την παράκλησή μου. Κύριε μας, συγχώρεσε εμένα, τους γονείς μου και τους πιστούς την Ημέρα που θα γίνει ο λογαριασμός.", "Η ντουέτα του Προφήτη Ιμπραήμ (AS) για τον ίδιο και τους απογόνους του.", "Κοινώς απαγγέλλεται στο τέλος της προσευχής."),
        "dua_newlywed" to DuaText("Συγχαρητήρια στους Νεόνυμφους", "Είθε ο Αλλάχ να σας ευλογεί, να σας στείλει ευλογίες και να σας φέρει και τους δύο μαζί με καλοσύνη.", "Όταν συγχαίρεις κάποιον για το γάμο του.", "Τα συγχαρητήρια Sunnah για έναν γάμο."),
        "dua_before_eating" to DuaText("Πριν από το φαγητό", "Στο όνομα του Αλλάχ. (Αν ξεχαστεί:) Στο όνομα του Αλλάχ, στην αρχή και στο τέλος του.", "Πριν το φαγητό. Αν το ξεχάσετε, πείτε το εν μέρει.", "Το να πεις Bismillah εμποδίζει τον Shaytan να μοιράζεται το φαγητό."),
        "dua_after_eating" to DuaText("Μετά το φαγητό", "Όλος ο έπαινος είναι για τον Αλλάχ που με τάισε αυτό και μου το παρείχε χωρίς καμία δύναμη ή δύναμη εκ μέρους μου.", "Μετά το τέλος του γεύματος.", "Τα περασμένα αμαρτήματα αυτού που το λέει συγχωρούνται."),
        "dua_host" to DuaText("Για τον οικοδεσπότη", "Ω Αλλάχ, ευλόγησε τους σε ό,τι τους παρείχες, συγχώρεσέ τους και ελέησέ τους.", "Για τον οικοδεσπότη, μετά το φαγητό στο σπίτι κάποιου.", "Ευχαριστώ τον οικοδεσπότη με τον τρόπο Sunnah."),
        "dua_breaking_fast" to DuaText("Κατά τη Λύση της Νηστείας", "Η δίψα έχει φύγει, οι φλέβες έχουν υγρανθεί και η ανταμοιβή επιβεβαιώνεται, αν θέλει ο Αλλάχ.", "Την ώρα του ιφτάρ.", "Ο Προφήτης ﷺ το είπε αυτό όταν έλυνε τη νηστεία του."),
        "dua_new_clothes" to DuaText("Φορώντας νέα ρούχα", "Ω Αλλάχ, όλος ο έπαινος είναι δικός Σου. Με ντύσατε με αυτό. Σου ζητώ το καλό του και το καλό αυτού για το οποίο δημιουργήθηκε, και σε Σένα ζητώ καταφύγιο από το κακό του και το κακό αυτού για το οποίο δημιουργήθηκε.", "Όταν φοράτε ένα νέο ένδυμα (ονομάζοντάς το, όπως πουκάμισο ή τουρμπάνι).", "Ο Προφήτης ﷺ έκανε αυτή τη ντουέτα όταν φορούσε ένα νέο ένδυμα. (Η καθημερινή ντουέτα για το ντύσιμο βρίσκεται στην ενότητα «Ντυθώ».)"),
        "dua_rabbana_atina" to DuaText("Καλό σε αυτόν τον κόσμο και στο επέκεινα", "Κύριε μας, δώσε μας καλό στον κόσμο αυτό και καλό στο επέκεινα, και φύλαξέ μας από την τιμωρία της φωτιάς.", "Η ντουά ο Προφήτης ﷺ έκανε πιο συχνά.", "Μια ντουέτα που συγκεντρώνει κάθε καλό αυτού του κόσμου και του επέκεινα."),
        "dua_rabbi_zidni_ilma" to DuaText("Αύξηση της Γνώσης", "Κύριε μου, αύξησέ με σε γνώση.", "Για αύξηση της γνώσης.", "Ο Αλλάχ διέταξε τον Προφήτη ﷺ να ζητήσει αύξηση σε τίποτα άλλο εκτός από τη γνώση."),
        "dua_musa_sharh_sadr" to DuaText("Άνοιγμα του στήθους (Musa AS)", "Κύριε μου, διεύρυνε το στήθος μου για μένα, διευκόλυνε μου το έργο μου και λύσε τον κόμπο από τη γλώσσα μου για να καταλάβουν τον λόγο μου.", "Πριν από μια εξέταση, μια ομιλία ή οποιαδήποτε δύσκολη εργασία.", "Η ντουά του Προφήτη Μούσα (AS) — ηρεμία καρδιάς και ευκολία στη δουλειά."),
        "dua_la_tuzigh" to DuaText("Σταθερότητα της Καρδιάς", "Κύριε μας, μην αφήσεις τις καρδιές μας να παρεκκλίνουν αφού μας καθοδήγησες και χάρισέ μας έλεος από τον εαυτό σου. Πράγματι, Εσύ είσαι ο Δωρητής.", "Για σταθερότητα στην καθοδήγηση.", "Μια δόξα για να παραμείνετε σταθεροί στην πίστη."),
        "dua_ya_muqallib" to DuaText("Ω Εσύ που στρέφεις τις καρδιές", "Ω γυριστή των καρδιών, κράτα την καρδιά μου σταθερή στη θρησκεία Σου.", "Ο Προφήτης ﷺ έκανε συχνά αυτή τη ντουά.", "Σύμφωνα με την Umm Salamah (RA), η ντουά ο Προφήτης ﷺ έκανε πιο συχνά."),
        "dua_la_tuakhidhna" to DuaText("Τελευταίοι στίχοι της Σούρας Αλ-Μπακάρα", "Κύριέ μας, μη μας αναγκάσεις αν ξεχάσουμε ή κάνουμε λάθος. Κύριε μας, μη μας βάζεις βάρος σαν αυτό που έβαλες σε αυτούς που ήταν πριν από εμάς. Κύριε μας, μη μας φορτώνεις με όσα δεν αντέχουμε. Συγχώρεσέ μας, συγχώρεσέ μας και ελέησέ μας. Είσαι ο Προστάτης μας, βοήθησέ μας λοιπόν ενάντια στους απίστους.", "Το βράδυ πριν από τον ύπνο - οι δύο τελευταίοι στίχοι της Σούρας αλ-Μπακάρα.", "Όποιος απαγγείλει τους δύο τελευταίους στίχους της Σούρας αλ-Μπακάρα τη νύχτα, θα του αρκούν."),
        "dua_visiting_sick" to DuaText("Επίσκεψη στον άρρωστο", "Ζητώ από τον Αλλάχ τον Ισχυρό, τον Κύριο του Ισχυρού Θρόνου, να σε θεραπεύσει.", "Επτά φορές όταν επισκέπτεται τον άρρωστο.", "Αν δεν έχει έρθει η ώρα του θανάτου, ο Αλλάχ θα τον θεραπεύσει."),
        "dua_ruqyah_pain" to DuaText("Για τον Σωματικό Πόνο", "Αναζητώ καταφύγιο στον Αλλάχ και τη δύναμή Του από το κακό αυτού που νιώθω και αυτού που φοβάμαι.", "Τοποθετήστε το χέρι σας εκεί που πονάει, πείτε Bismillah τρεις φορές και μετά αυτή τη ντουά επτά φορές.", "Ο Προφήτης ﷺ το δίδαξε στον Uthman ibn Abil-'As (RA) για πόνο."),
        "dua_ruqyah_nabawi" to DuaText("Προφητική Ruqyah για τους άρρωστους", "Ω Αλλάχ, Κύριε της ανθρωπότητας! Απομάκρυνε το κακό και δώσε θεραπεία, γιατί εσύ είσαι αυτός που θεραπεύει. δεν υπάρχει θεραπεία εκτός από τη θεραπεία Σου — μια θεραπεία που δεν αφήνει καμία ασθένεια πίσω.", "Περνώντας το χέρι πάνω από τον άρρωστο.", "Ο Προφήτης ﷺ το απήγγειλε αυτό όταν επισκεπτόταν άρρωστα μέλη της οικογένειάς του."),
        "dua_kalimat_tammat" to DuaText("Αναζητώντας καταφύγιο με τέλεια λόγια", "Αναζητώ καταφύγιο στα τέλεια λόγια του Αλλάχ από το κακό αυτού που δημιούργησε.", "Όταν σταματάτε σε ένα μέρος ή το βράδυ.", "Όποιος σταματήσει σε ένα μέρος και το πει αυτό, τίποτα δεν θα του κάνει κακό μέχρι να το αφήσει."),
        "dua_evil_eye" to DuaText("Προστασία για παιδιά (Κακό Μάτι)", "Αναζητώ προστασία για εσάς και στα τέλεια λόγια του Αλλάχ από κάθε διάβολο και κάθε δηλητηριώδες πλάσμα, και από κάθε βλαβερό μάτι.", "Ο Προφήτης ﷺ το απήγγειλε αυτό στον Χασάν και τον Χουσεΐν (RA).", "Μια ντουέτα Sunnah για την προστασία των παιδιών από το κακό μάτι και τη βλάβη (για ένα παιδί πείτε «U'īdhuka»)."),
        "dua_seeing_afflicted" to DuaText("Βλέποντας κάποιον σε δίκη", "Όλος ο έπαινος είναι για τον Αλλάχ που με γλίτωσε από αυτά με τα οποία σας δοκίμασε και με ευνόησε σε μεγάλο μέρος της δημιουργίας Του.", "Όταν βλέπετε κάποιον σε δοκιμασία (πείτε το ήσυχα στον εαυτό σας).", "Αυτός που το λέει κρατιέται ασφαλής από εκείνη τη δοκιμασία."),
        "dua_istikhara" to DuaText("Salat al-Istikhara", "Ω Αλλάχ, αναζητώ το καλό μέσω της γνώσης Σου, αναζητώ την ικανότητα μέσω της δύναμής Σου, και Σου ζητώ τη μεγάλη γενναιοδωρία Σου. Εσύ έχεις δύναμη και εγώ δεν έχω καμία. Εσύ ξέρεις και εγώ όχι, και Εσύ είσαι ο Γνωριστής του αόρατου. Ω Αλλάχ, αν κατά τη γνώση Σου αυτό το θέμα (φέρε το στο νου) είναι καλό για τη θρησκεία μου, τη ζωή μου και το τέλος μου, τότε όρισε το για μένα, διευκόλυνε με και ευλόγησέ με σε αυτό. Και αν κατά τη γνώση Σου αυτό το θέμα είναι κακό για τη θρησκεία μου, τη ζωή μου και το τέλος μου, τότε απομάκρυνέ το από εμένα και απομάκρυνέ με από αυτό, και ορίστε για μένα το καλό όπου κι αν είναι, τότε κάντε με να ικανοποιηθώ με αυτό.", "Μετά από δύο ρακέτες εκούσιας προσευχής, να αναζητήσετε το καλύτερο σε μια επιτρεπτή υπόθεση.", "Ο Προφήτης ﷺ δίδαξε στους συντρόφους istikhara σε όλα τα θέματα καθώς τους δίδαξε μια σούρα του Κορανίου."),
    )
}
